SELECT '==NOTAS RECUPERABLES PARA ITEMS DELETED (1766, 1842-1845, 1928, 2049, 2435, 2785, 3094) ==' as '';
SELECT t.itemid, gi.itemname AS activity, gi.iteminstance AS assign_id, t.userid, u.firstname, u.lastname, t.finalgrade, t.dt FROM (SELECT gh.itemid, gh.userid, gh.finalgrade, from_unixtime(gh.timemodified) dt, ROW_NUMBER() OVER (PARTITION BY gh.itemid, gh.userid ORDER BY gh.timemodified DESC) AS rn FROM isi_grade_grades_history gh WHERE gh.itemid IN (1766, 1842, 1843, 1844, 1845, 1928, 2049, 2435, 2785, 3094) AND gh.finalgrade IS NOT NULL AND gh.finalgrade >= 0) t LEFT JOIN isi_grade_items gi ON gi.id = t.itemid LEFT JOIN isi_user u ON u.id = t.userid WHERE t.rn = 1 ORDER BY t.itemid, t.userid;
SELECT '==SUMMARY DE NOTAS RECUPERABLES POR ITEM ==' as '';
SELECT gh.itemid, COUNT(DISTINCT gh.userid) AS students_graded, COUNT(*) AS grade_records FROM isi_grade_grades_history gh WHERE gh.itemid IN (1766, 1842, 1843, 1844, 1845, 1928, 2049, 2435, 2785, 3094) AND gh.finalgrade IS NOT NULL AND gh.finalgrade >= 0 GROUP BY gh.itemid;
